/* 학습 해설
 * Waitqueue flags·표시 비트 정의와 콜백 전 snapshot
 * 실제 Linux 대기열의 구조와 등록·조건 검사·깨움·정리 순서를 읽어 잠드는 기술의 사용 조건을 배웁니다.
 * 헤더는 EXCLUSIVE, WOKEN, CUSTOM, DONE, PRIORITY를 각각 다른 비트 값으로 정의합니다. 선언된 비트가 모두 공통 깨움 함수의 필터는 아닙니다. 공통 순회는 콜백 전 flags를 지역 변수로 읽고 그 snapshot의 EXCLUSIVE로 예산 소비를 결정합니다. PRIORITY는 등록 위치에, WOKEN은 별도 woken 프로토콜에 사용합니다. CUSTOM과 DONE의 개별 의미는 이 파일의 일반 순회가 자동으로 구현하지 않습니다.
 * flag 선언, 실제로 읽는 함수와 사용자 콜백 규약을 구별하세요. 콜백이 실행 중 EXCLUSIVE를 바꾸면 같은 호출의 예산 판단은 이미 읽은 값에 근거합니다. 사용자 표시 비트를 설정했다는 사실만으로 공통 순회가 task를 건너뛴다고 가정하지 마세요.
 */
struct wait_queue_entry {
	unsigned int		flags;
	void			*private;
	wait_queue_func_t	func;
	struct list_head	entry;
};

struct wait_queue_head {
	spinlock_t		lock;
	struct list_head	head;
};
typedef struct wait_queue_head wait_queue_head_t;

struct task_struct;

/*
 * Macros for declaration and initialisaton of the datatypes
 */

#define __WAITQUEUE_INITIALIZER(name, tsk) {					\
	.private	= tsk,							\
	.func		= default_wake_function,				\
	.entry		= { NULL, NULL } }

#define DECLARE_WAITQUEUE(name, tsk)						\
	struct wait_queue_entry name = __WAITQUEUE_INITIALIZER(name, tsk)

/* 학습 해설
 * Swait 설계·제한된 기능으로 잠금 구간 줄이기
 * 실제 simple waitqueue의 기능 제한, raw 잠금과 task 등록·깨움·정리 순서를 통해 실시간 대기 기술의 사용 조건을 배웁니다.
 * simple waitqueue는 일반 waitqueue의 모든 기능을 제공하지 않습니다. 사용자 깨움 콜백과 비 exclusive 모드를 없애고, 같은 대기열에서 서로 다른 수면 유형을 섞는 사용을 제한합니다. 모든 깨움은 TASK_NORMAL을 대상으로 하며 swake_up_one은 첫 항목 하나를 처리합니다. raw spinlock을 사용할 수 있도록 임의 콜백의 실행 시간을 제거한 설계입니다. 헤더는 특별한 실시간 제약이 있는 경우에만 사용하고 보통은 일반 waitqueue를 권합니다.
 * 사용자 콜백, poll 이벤트, 서로 다른 대기 state 필터가 필요하면 일반 waitqueue를 검토하세요. 모든 기능을 가진 빠른 대기열이라고 생각하지 마세요. 필요한 기능을 줄여 잠금·IRQ 보유 구간을 제한한다는 원리를 확인합니다.
 */
struct swait_queue_head {
	raw_spinlock_t		lock;
	struct list_head	task_list;
};

struct swait_queue {
	struct task_struct	*task;
	struct list_head	task_list;
};

#define __SWAITQUEUE_INITIALIZER(name) {				\
	.task		= current,					\
	.task_list	= LIST_HEAD_INIT((name).task_list),		\
}

#define DECLARE_SWAITQUEUE(name)					\
	struct swait_queue name = __SWAITQUEUE_INITIALIZER(name)

#define __SWAIT_QUEUE_HEAD_INITIALIZER(name) {				\
	.lock		= __RAW_SPIN_LOCK_UNLOCKED(name.lock),		\
	.task_list	= LIST_HEAD_INIT((name).task_list),		\
}

#define DECLARE_SWAIT_QUEUE_HEAD(name)					\
	struct swait_queue_head name = __SWAIT_QUEUE_HEAD_INITIALIZER(name)

/* 학습 해설
 * Swait 자료구조·task와 raw spinlock
 * 실제 simple waitqueue의 기능 제한, raw 잠금과 task 등록·깨움·정리 순서를 통해 실시간 대기 기술의 사용 조건을 배웁니다.
 * swait_queue는 task 포인터와 리스트 링크만 가집니다. 일반 wait_queue_entry의 flags, private와 func가 없습니다. head는 raw_spinlock_t와 task_list 센티널입니다. 작은 항목 표현과 고정 깨움 동작이 임의 콜백을 실행하지 않는 설계에 맞물립니다. 자료형이 다르므로 일반 waitqueue 항목과 head를 서로 바꿔 전달할 수 없습니다.
 * 구조체의 두 멤버를 현재 task 등록과 리스트 연결로 구별하세요. 별도 콜백이나 이벤트 key를 추가하려고 일반 waitqueue API에 캐스팅하지 마세요. 객체 수명은 연결된 항목과 깨움이 더 이상 접근하지 않을 때까지 유지합니다.
 */
struct swait_queue {
	struct task_struct	*task;
	struct list_head	task_list;
};

#define __SWAITQUEUE_INITIALIZER(name) {				\
	.task		= current,					\
	.task_list	= LIST_HEAD_INIT((name).task_list),		\
}

#define DECLARE_SWAITQUEUE(name)					\
	struct swait_queue name = __SWAITQUEUE_INITIALIZER(name)

#define __SWAIT_QUEUE_HEAD_INITIALIZER(name) {				\
	.lock		= __RAW_SPIN_LOCK_UNLOCKED(name.lock),		\
	.task_list	= LIST_HEAD_INIT((name).task_list),		\
}

#define DECLARE_SWAIT_QUEUE_HEAD(name)					\
	struct swait_queue_head name = __SWAIT_QUEUE_HEAD_INITIALIZER(name)

extern void __init_swait_queue_head(struct swait_queue_head *q, const char *name,
				    struct lock_class_key *key);

#define init_swait_queue_head(q)				\
	do {							\

/* 학습 해설
 * Swait 초기화·정적 선언과 실행 중 head 설정
 * 실제 simple waitqueue의 기능 제한, raw 잠금과 task 등록·깨움·정리 순서를 통해 실시간 대기 기술의 사용 조건을 배웁니다.
 * head 초기화 함수는 raw spinlock을 초기화하고 lockdep 클래스와 이름을 연결한 뒤 task_list를 자기 참조로 만듭니다. 헤더의 정적 head 선언도 잠금과 빈 리스트를 구성합니다. DECLARE_SWAITQUEUE는 current와 자기 참조 항목 링크를 설정합니다. CONFIG_LOCKDEP의 스택 head 선언은 실행 중 초기화를 사용하여 잠금 분류를 준비합니다.
 * 새 head는 사용 전에 초기화하고, 사용 중인 리스트를 재초기화하지 마세요. 스택 대기 항목의 수명과 대기 등록 기간을 맞춥니다. 현재 task를 설정하는 정적 지역 항목 선언과 head 선언을 구별합니다.
 */
void __init_swait_queue_head(struct swait_queue_head *q, const char *name,
			     struct lock_class_key *key)
{
	raw_spin_lock_init(&q->lock);
	lockdep_set_class_and_name(&q->lock, key, name);
	INIT_LIST_HEAD(&q->task_list);
}
EXPORT_SYMBOL(__init_swait_queue_head);

/*
 * The thing about the wake_up_state() return value; I think we can ignore it.
 *
 * If for some reason it would return 0, that means the previously waiting
 * task is already running, so it will observe condition true (or has already).
 */
void swake_up_locked(struct swait_queue_head *q, int wake_flags)
{
	struct swait_queue *curr;

	if (list_empty(&q->task_list))
		return;

	curr = list_first_entry(&q->task_list, typeof(*curr), task_list);
	try_to_wake_up(curr->task, TASK_NORMAL, wake_flags);
	list_del_init(&curr->task_list);
}

/* 학습 해설
 * Swait active·조건 공개와 배리어
 * 실제 simple waitqueue의 기능 제한, raw 잠금과 task 등록·깨움·정리 순서를 통해 실시간 대기 기술의 사용 조건을 배웁니다.
 * swait_active는 task_list가 비었는지 잠금 없이 조회합니다. 원문은 일반 waitqueue_active와 같은 놓친 깨움 위험을 명시합니다. 조건을 바꾼 waker가 이 조회로 깨움을 생략하려면 잠금 또는 명시적 smp_mb 규약을 지켜야 합니다. swq_has_sleeper는 smp_mb 뒤 active를 호출합니다. 기능이 단순해져도 task 등록과 조건 관측의 메모리 순서 문제까지 사라지는 것은 아닙니다.
 * 조건 저장, 배리어, 리스트 관측과 waiter의 준비·조건 재검사 순서를 함께 표시하세요. active가 true라는 사실만으로 task가 지금 잠들어 있거나 객체 수명을 소유한다고 가정하지 않습니다.
 */
static inline int swait_active(struct swait_queue_head *wq)
{
	return !list_empty(&wq->task_list);
}

/**
 * swq_has_sleeper - check if there are any waiting processes
 * @wq: the waitqueue to test for waiters
 *
 * Returns true if @wq has waiting processes
 *
 * Please refer to the comment for swait_active.
 */
static inline bool swq_has_sleeper(struct swait_queue_head *wq)
{
	/*
	 * We need to be sure we are in sync with the list_add()
	 * modifications to the wait queue (task_list).
	 *
	 * This memory barrier should be paired with one on the
	 * waiting side.
	 */
	smp_mb();
	return swait_active(wq);
}

/* 학습 해설
 * Swait locked wake·첫 항목 제거와 깨움 결과
 * 실제 simple waitqueue의 기능 제한, raw 잠금과 task 등록·깨움·정리 순서를 통해 실시간 대기 기술의 사용 조건을 배웁니다.
 * swake_up_locked는 비어 있으면 끝내고, 첫 항목의 task에 TASK_NORMAL과 지정 wake_flags로 try_to_wake_up을 호출합니다. 그 반환값을 검사하지 않고 list_del_init으로 항목을 제거합니다. 이미 실행 중이라 깨움 결과가 0이어도 항목 제거는 진행됩니다. 일반 autoremove 콜백의 성공 때만 제거하는 계약과 다릅니다. 호출자는 raw head 잠금을 보유한 문맥을 지켜야 합니다.
 * 깨움 결과와 등록 제거를 구별하세요. 다시 기다려야 하면 조건 반복문이 항목을 재등록합니다. 내부 locked 함수를 head 잠금 없이 호출하거나 별도 task 상태 필터를 기대하지 마세요.
 */
void swake_up_locked(struct swait_queue_head *q, int wake_flags)
{
	struct swait_queue *curr;

	if (list_empty(&q->task_list))
		return;

	curr = list_first_entry(&q->task_list, typeof(*curr), task_list);
	try_to_wake_up(curr->task, TASK_NORMAL, wake_flags);
	list_del_init(&curr->task_list);
}
EXPORT_SYMBOL(swake_up_locked);

/*
 * Wake up all waiters. This is an interface which is solely exposed for
 * completions and not for general usage.
 *
 * It is intentionally different from swake_up_all() to allow usage from
 * hard interrupt context and interrupt disabled regions.
 */
void swake_up_all_locked(struct swait_queue_head *q)
{
	while (!list_empty(&q->task_list))
		swake_up_locked(q, 0);
}

/* 학습 해설
 * Swait wake one·IRQ 상태 보존과 한 항목
 * 실제 simple waitqueue의 기능 제한, raw 잠금과 task 등록·깨움·정리 순서를 통해 실시간 대기 기술의 사용 조건을 배웁니다.
 * swake_up_one은 raw_spin_lock_irqsave로 head를 보호하고 locked wake를 한 번 호출한 뒤 이전 IRQ 상태를 복구합니다. 항목이 없으면 잠금 구간 안에서 아무 task도 처리하지 않습니다. 한 항목의 처리는 여러 task 중 조건을 실제 소비한 task가 정확히 한 명임을 증명하지는 않습니다. 호출자는 조건 변경과 task가 다시 검사하는 프로토콜을 함께 유지합니다.
 * 일부 대기자만 처리하는 사건에서 단일 항목 깨움과 실제 공유 자원 소비를 구분합니다. IRQ가 원래 꺼진 문맥에서도 save·restore 규약을 확인하세요. 반환 결과로 작업 완료를 판단하지 않습니다.
 */
void swake_up_one(struct swait_queue_head *q)
{
	unsigned long flags;

	raw_spin_lock_irqsave(&q->lock, flags);
	swake_up_locked(q, 0);
	raw_spin_unlock_irqrestore(&q->lock, flags);
}
EXPORT_SYMBOL(swake_up_one);

/*
 * Does not allow usage from IRQ disabled, since we must be able to
 * release IRQs to guarantee bounded hold time.
 */
void swake_up_all(struct swait_queue_head *q)
{
	struct swait_queue *curr;
	LIST_HEAD(tmp);

	raw_spin_lock_irq(&q->lock);
	list_splice_init(&q->task_list, &tmp);
	while (!list_empty(&tmp)) {
		curr = list_first_entry(&tmp, typeof(*curr), task_list);

		wake_up_state(curr->task, TASK_NORMAL);
		list_del_init(&curr->task_list);

/* 학습 해설
 * Swait wake all·snapshot 리스트와 반복 잠금 해제
 * 실제 simple waitqueue의 기능 제한, raw 잠금과 task 등록·깨움·정리 순서를 통해 실시간 대기 기술의 사용 조건을 배웁니다.
 * swake_up_all은 IRQ를 끄고 raw 잠금을 잡아 기존 task_list를 임시 리스트로 옮깁니다. 각 task를 깨우고 항목을 제거하며, 남은 항목이 있으면 잠금과 IRQ를 풀었다가 다시 잡습니다. 따라서 여러 항목을 처리하는 동안 상위 우선순위 task가 실행할 기회를 얻습니다. 임시 리스트를 만든 뒤 head에 새로 등록된 task는 이번 임시 리스트의 대상에 자동 포함되지 않습니다. 원문은 IRQ가 이미 꺼진 문맥에서 이 함수를 사용하지 못한다고 명시합니다.
 * IRQ가 활성인 사용 문맥과 등록 시점 snapshot을 확인하세요. all이라는 이름을 호출 중 모든 새 등록까지 끝없이 처리하는 보장으로 해석하지 마세요. 각 잠금 구간을 제한하려는 목적과 함수 전체의 O(n) 작업량을 구별합니다.
 */
void swake_up_all(struct swait_queue_head *q)
{
	struct swait_queue *curr;
	LIST_HEAD(tmp);

	raw_spin_lock_irq(&q->lock);
	list_splice_init(&q->task_list, &tmp);
	while (!list_empty(&tmp)) {
		curr = list_first_entry(&tmp, typeof(*curr), task_list);

		wake_up_state(curr->task, TASK_NORMAL);
		list_del_init(&curr->task_list);

		if (list_empty(&tmp))
			break;

		raw_spin_unlock_irq(&q->lock);
		raw_spin_lock_irq(&q->lock);
	}
	raw_spin_unlock_irq(&q->lock);
}
EXPORT_SYMBOL(swake_up_all);

void __prepare_to_swait(struct swait_queue_head *q, struct swait_queue *wait)
{
	wait->task = current;

/* 학습 해설
 * Swait all locked·completion 전용 예외
 * 실제 simple waitqueue의 기능 제한, raw 잠금과 task 등록·깨움·정리 순서를 통해 실시간 대기 기술의 사용 조건을 배웁니다.
 * all locked 함수는 리스트가 빌 때까지 locked wake를 반복하며 항목 사이에 잠금을 풀지 않습니다. 원문은 이 인터페이스가 completion을 위해서만 노출되며 일반 사용용이 아니라고 명시합니다. swake_up_all과 달리 hard IRQ와 IRQ 비활성 문맥을 허용하려는 별도 설계입니다. 따라서 모든 all 함수가 반복마다 잠금을 풀어 보유 시간을 제한한다고 일반화하면 안 됩니다.
 * completion의 상위 잠금과 호출 계약에서 사용법을 확인하세요. 일반 swait 사용자에게 IRQ-off 우회 함수로 임의 권하지 않습니다. 기능 범위와 예외 문맥을 원문 주석에 맞춰 구별합니다.
 */
void swake_up_all_locked(struct swait_queue_head *q)
{
	while (!list_empty(&q->task_list))
		swake_up_locked(q, 0);
}

void swake_up_one(struct swait_queue_head *q)
{
	unsigned long flags;

	raw_spin_lock_irqsave(&q->lock, flags);
	swake_up_locked(q, 0);
	raw_spin_unlock_irqrestore(&q->lock, flags);
}
EXPORT_SYMBOL(swake_up_one);

