/* 학습 해설
 * Semaphore 느린 대기·스택 waiter와 grant 우선
 * 원문 counting semaphore의 남은 허가 수와 FIFO grant, 잠금·수면·signal·timeout을 읽어 자원 제한 기술의 사용 조건을 배웁니다.
 * 느린 공통 함수는 스택 semaphore_waiter를 tail에 넣고 current와 up=false를 설정합니다. 반복에서 signal, 시간 만료를 검사한 뒤 대기 상태를 설정하고 잠금을 풀어 schedule_timeout합니다. 돌아와 잠금을 잡으면 waiter.up을 먼저 확인하여 true이면 성공 0을 반환합니다. 따라서 그 대기 중 허가가 전달되면 다음 반복의 signal·timeout 검사보다 grant 확인이 앞섭니다. 허가를 받지 못한 중단 경로는 자신의 항목을 제거합니다.
 * 등록, 수면, 재획득과 grant의 판정 순서를 표시하세요. 깨움만으로 성공한다고 가정하지 말고 up 플래그를 확인합니다. 지역 waiter의 수명은 리스트에서 제거되거나 grant 전달된 경로와 함께 추적합니다.
 */
static inline int __sched ___down_common(struct semaphore *sem, long state,
								long timeout)
{
	struct semaphore_waiter waiter;

	list_add_tail(&waiter.list, &sem->wait_list);
	waiter.task = current;
	waiter.up = false;

	for (;;) {
		if (signal_pending_state(state, current))
			goto interrupted;
		if (unlikely(timeout <= 0))
			goto timed_out;
		__set_current_state(state);
		raw_spin_unlock_irq(&sem->lock);
		timeout = schedule_timeout(timeout);
		raw_spin_lock_irq(&sem->lock);
		if (waiter.up)
			return 0;
	}

 timed_out:
	list_del(&waiter.list);
	return -ETIME;

/* 학습 해설
 * Semaphore up·빈 리스트 증가와 직접 허가 전달
 * 원문 counting semaphore의 남은 허가 수와 FIFO grant, 잠금·수면·signal·timeout을 읽어 자원 제한 기술의 사용 조건을 배웁니다.
 * up은 irqsave raw 잠금 아래 리스트를 검사합니다. 비어 있으면 count를 하나 늘립니다. waiter가 있으면 __up이 첫 항목을 제거하고 waiter.up=true로 설정한 뒤 task를 깨웁니다. 이 경로에서는 count를 증가시키지 않으므로 이미 선택한 waiter에게 직접 허가가 전달됩니다. 새 task가 count의 증가를 먼저 소비하여 그 허가를 빼앗는 경로와 구별됩니다.
 * 반환을 현재 waiter에 직접 전달하는 경우와 향후 획득을 위해 저장하는 경우를 구별하세요. up은 소유자 검사를 하지 않으므로 호출자 프로토콜로 균형과 유한 허가 범위를 지킵니다. 함수가 임의 overflow를 막는 포화 counter라고 가정하지 않습니다.
 */
void __sched up(struct semaphore *sem)
{
	unsigned long flags;

	raw_spin_lock_irqsave(&sem->lock, flags);
	if (likely(list_empty(&sem->wait_list)))
		sem->count++;
	else
		__up(sem);
	raw_spin_unlock_irqrestore(&sem->lock, flags);
}
EXPORT_SYMBOL(up);

/* Functions for the contended case */

struct semaphore_waiter {
	struct list_head list;
	struct task_struct *task;
	bool up;
};

/*
 * Because this function is inlined, the 'state' parameter will be
 * constant, and thus optimised away by the compiler.  Likewise the
