 */

/* 학습 해설
 * Semaphore 경합 추적·공통 wrapper와 고정 인자
 * 원문 counting semaphore의 남은 허가 수와 FIFO grant, 잠금·수면·signal·timeout을 읽어 자원 제한 기술의 사용 조건을 배웁니다.
 * __down_common은 trace_contention_begin을 호출하고 실제 ___down_common의 결과를 얻은 뒤 trace_contention_end에 결과를 전달합니다. 바깥 __down 계열 wrapper는 state와 timeout을 고정하여 공통 알고리즘에 전달합니다. 원문은 inline 과정에서 상수 state와 시간 인자가 최적화될 수 있다고 설명합니다. tracepoint 호출은 실제 경합을 관측하는 연결점이며 자체가 허가 소비나 잠금 정책을 바꾸지는 않습니다.
 * 실제 대기 알고리즘과 그 앞뒤 계측 wrapper를 구별합니다. trace 이벤트에 성공·signal·timeout 결과가 어디서 전달되는지 따라갑니다. 사용자 공간 직렬 모델의 hook 기록을 실제 커널 ftrace나 시간 측정으로 주장하지 않습니다.
 */
static inline int __sched __down_common(struct semaphore *sem, long state,
					long timeout)
{
	int ret;

	trace_contention_begin(sem, 0);
	ret = ___down_common(sem, state, timeout);
	trace_contention_end(sem, ret);

	return ret;
}

static noinline void __sched __down(struct semaphore *sem)
{
	__down_common(sem, TASK_UNINTERRUPTIBLE, MAX_SCHEDULE_TIMEOUT);
}

static noinline int __sched __down_interruptible(struct semaphore *sem)
{
	return __down_common(sem, TASK_INTERRUPTIBLE, MAX_SCHEDULE_TIMEOUT);
}

static noinline int __sched __down_killable(struct semaphore *sem)
{
	return __down_common(sem, TASK_KILLABLE, MAX_SCHEDULE_TIMEOUT);
}

/* 학습 해설
 * Semaphore count 경계·unsigned 계산과 int 변환
 * 원문 counting semaphore의 남은 허가 수와 FIFO grant, 잠금·수면·signal·timeout을 읽어 자원 제한 기술의 사용 조건을 배웁니다.
 * 저장 count는 unsigned int이므로 count - 1은 unsigned 계산입니다. 결과를 int에 저장한 뒤 음수 여부로 try 획득을 판정합니다. 검증한 GNU C의 32비트 int 구성에서 count=INT_MAX+2를 주입하면 양수 저장 값인데도 int 중간값이 음수가 되어 실패합니다. up의 빈 리스트 분기에는 completion 같은 포화 guard가 없으므로 UINT_MAX 다음은 0으로 wrap합니다. 이것은 정상적인 균형 자원 사용 범위 밖의 경계 관찰이며 모든 플랫폼의 signed 변환 결과를 일반화하는 주장이 아닙니다.
 * 호출자는 유효한 초기 자원 수와 소비·반환 균형을 지키세요. 실제 프로그램에서 멤버를 직접 바꾸지 않습니다. unsigned 표현식, signed 저장과 비교를 단계로 나누어 C 자료형의 변환 원리를 읽습니다.
 */
int __sched down_trylock(struct semaphore *sem)
{
	unsigned long flags;
	int count;

	raw_spin_lock_irqsave(&sem->lock, flags);
	count = sem->count - 1;
	if (likely(count >= 0))
		sem->count = count;
	raw_spin_unlock_irqrestore(&sem->lock, flags);

	return (count < 0);
}
EXPORT_SYMBOL(down_trylock);

